public class OrderService {
    public OrderResult placeOrder(String customerId, List<ItemRequest> items, AddressRequest addr, boolean vip, String couponCode) {
        // 参数校验
        if (customerId == null || customerId.isEmpty()) throw new IllegalArgumentException("customerId");
        if (items == null || items.isEmpty()) throw new IllegalArgumentException("items");
        if (addr == null) throw new IllegalArgumentException("address");
        if (addr.getProvince() == null || addr.getCity() == null || addr.getDistrict() == null || addr.getDetail() == null) {
            throw new IllegalArgumentException("address fields");
        }

        // 查客户
        Customer customer = customerMapper.selectById(customerId);
        if (customer == null) throw new CustomerNotFoundException(customerId);
        if (customer.getStatus() != 1) throw new IllegalStateException("customer disabled");

        // 校验库存
        Map<String, Integer> stockMap = new HashMap<>();
        for (ItemRequest item : items) {
            Product p = productMapper.selectById(item.getProductId());
            if (p == null) throw new ProductNotFoundException(item.getProductId());
            Integer stock = inventoryMapper.selectStock(item.getProductId());
            if (stock < item.getQuantity()) throw new InsufficientStockException(item.getProductId());
            stockMap.put(item.getProductId(), item.getQuantity());
        }

        // 计算商品金额
        BigDecimal itemsTotal = BigDecimal.ZERO;
        for (ItemRequest item : items) {
            Product p = productMapper.selectById(item.getProductId());
            BigDecimal subtotal = p.getPrice().multiply(BigDecimal.valueOf(item.getQuantity()));
            itemsTotal = itemsTotal.add(subtotal);
        }

        // 计算运费
        double weight = 0;
        for (ItemRequest item : items) {
            Product p = productMapper.selectById(item.getProductId());
            weight += p.getWeight() * item.getQuantity();
        }
        BigDecimal shipping;
        if (weight > 5) shipping = BigDecimal.valueOf(weight * 2.5);
        else shipping = BigDecimal.valueOf(10);
        if (vip) shipping = shipping.multiply(BigDecimal.valueOf(0.8));
        if ("BEIJING".equals(addr.getProvince()) || "SHANGHAI".equals(addr.getProvince())) {
            shipping = shipping.multiply(BigDecimal.valueOf(1.2));
        }

        // 应用优惠券
        BigDecimal discount = BigDecimal.ZERO;
        if (couponCode != null && !couponCode.isEmpty()) {
            Coupon coupon = couponMapper.selectByCode(couponCode);
            if (coupon == null) throw new CouponNotFoundException(couponCode);
            if (coupon.getStatus() != 1) throw new IllegalStateException("coupon used or expired");
            if (coupon.getMinAmount() != null && itemsTotal.compareTo(coupon.getMinAmount()) < 0) {
                throw new IllegalStateException("min amount not reached");
            }
            if (coupon.getType() == 1) discount = coupon.getValue();
            else if (coupon.getType() == 2) discount = itemsTotal.multiply(coupon.getValue()).divide(BigDecimal.valueOf(100));
            couponMapper.markUsed(coupon.getId());
        }

        // 计算最终金额
        BigDecimal finalAmount = itemsTotal.add(shipping).subtract(discount);
        if (finalAmount.compareTo(BigDecimal.ZERO) < 0) finalAmount = BigDecimal.ZERO;

        // 落库
        Order order = new Order();
        order.setId(UUID.randomUUID().toString());
        order.setCustomerId(customerId);
        order.setItemsAmount(itemsTotal);
        order.setShippingAmount(shipping);
        order.setDiscountAmount(discount);
        order.setFinalAmount(finalAmount);
        order.setStatus(0);
        order.setProvince(addr.getProvince());
        order.setCity(addr.getCity());
        order.setDistrict(addr.getDistrict());
        order.setDetailAddress(addr.getDetail());
        order.setCreatedAt(new Date());
        orderMapper.insert(order);

        for (ItemRequest item : items) {
            OrderItem oi = new OrderItem();
            oi.setOrderId(order.getId());
            oi.setProductId(item.getProductId());
            oi.setQuantity(item.getQuantity());
            orderItemMapper.insert(oi);
            inventoryMapper.decreaseStock(item.getProductId(), item.getQuantity());
        }

        // 发邮件
        try {
            new SmtpEmailSender().send(customer.getEmail(), "Order placed: " + order.getId());
        } catch (Exception e) {
            log.error("send email failed", e);
        }

        return new OrderResult(order.getId(), finalAmount);
    }
}
