public class DiscountCalculator {
    public BigDecimal calculate(String customerId, BigDecimal amount, String productCategory) {
        // 直接 new 数据库连接
        DbConnection conn = new DbConnection("jdbc:mysql://prod-db/order", "root", "pwd");
        // 静态调用读取配置
        DiscountConfig config = ConfigLoader.load("discount.properties");

        Customer customer = conn.queryCustomer(customerId);
        BigDecimal discount = BigDecimal.ZERO;

        if (customer.getLevel() == 5) {
            discount = amount.multiply(BigDecimal.valueOf(config.getVipRate()));
        } else if (customer.getLevel() == 3 || customer.getLevel() == 4) {
            discount = amount.multiply(BigDecimal.valueOf(config.getGoldRate()));
        } else {
            discount = amount.multiply(BigDecimal.valueOf(0.05));
        }

        // 按品类再调整
        if ("ELECTRONICS".equals(productCategory)) {
            discount = discount.multiply(BigDecimal.valueOf(0.8));
        } else if ("FOOD".equals(productCategory)) {
            discount = discount.multiply(BigDecimal.valueOf(1.2));
        }

        // 限制最大折扣
        BigDecimal maxDiscount = amount.multiply(BigDecimal.valueOf(0.5));
        if (discount.compareTo(maxDiscount) > 0) discount = maxDiscount;

        // 静态调用记日志
        Logger.log("discount calculated: " + discount);

        return discount;
    }
}
